import{_ as i,a as r,e as t,l as a,ar as d,O as o,t as c}from"./chunks/framework.CK3qJuPR.js";const m=JSON.parse('{"title":"webpack 基础知识","description":"","frontmatter":{"title":"webpack 基础知识","tags":["interview","webpack"]},"headers":[],"relativePath":"interview/webpack.md","filePath":"interview/webpack.md","lastUpdated":1761045430000}'),n={name:"interview/webpack.md"},h={id:"frontmatter-title",tabindex:"-1"};function b(l,e,s,p,k,u){return t(),r("div",null,[e[1]||(e[1]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/interview/webpack.md for this page in Markdown format",-1)),a("h1",h,[o(c(l.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),e[2]||(e[2]=d('<h1 id="webpack-面试题总结" tabindex="-1">Webpack 面试题总结 <a class="header-anchor" href="#webpack-面试题总结" aria-label="Permalink to “Webpack 面试题总结”">​</a></h1><h2 id="🌟-webpack-基础概念" tabindex="-1">🌟 Webpack 基础概念 <a class="header-anchor" href="#🌟-webpack-基础概念" aria-label="Permalink to “🌟 Webpack 基础概念”">​</a></h2><h3 id="什么是-webpack" tabindex="-1">什么是 Webpack？ <a class="header-anchor" href="#什么是-webpack" aria-label="Permalink to “什么是 Webpack？”">​</a></h3><p>Webpack 是一个现代 JavaScript 应用程序的静态模块打包工具。它会递归构建依赖关系图，并将所有模块打包成一个或多个 bundle 文件。</p><h3 id="webpack-的核心概念" tabindex="-1">Webpack 的核心概念 <a class="header-anchor" href="#webpack-的核心概念" aria-label="Permalink to “Webpack 的核心概念”">​</a></h3><ul><li><strong>Entry（入口）</strong>：Webpack 构建的起点，指定从哪个文件开始打包。</li><li><strong>Output（输出）</strong>：打包后的文件输出位置和文件名。</li><li><strong>Loader</strong>：用于转换模块的转换器，例如处理 JS、CSS、图片等非 JS 文件。</li><li><strong>Plugin</strong>：扩展 Webpack 功能，在构建流程的不同阶段执行操作。</li><li><strong>Module</strong>：Webpack 处理的单个文件或资源。</li><li><strong>Chunk</strong>：Webpack 打包生成的代码块，用于按需加载。</li><li><strong>Bundle</strong>：最终输出的文件。</li></ul><hr><h2 id="⚡-常见-webpack-面试题" tabindex="-1">⚡ 常见 Webpack 面试题 <a class="header-anchor" href="#⚡-常见-webpack-面试题" aria-label="Permalink to “⚡ 常见 Webpack 面试题”">​</a></h2><h3 id="_1️⃣-webpack-与其他打包工具-如-parcel、vite-区别" tabindex="-1">1️⃣ Webpack 与其他打包工具（如 Parcel、Vite）区别 <a class="header-anchor" href="#_1️⃣-webpack-与其他打包工具-如-parcel、vite-区别" aria-label="Permalink to “1️⃣ Webpack 与其他打包工具（如 Parcel、Vite）区别”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>特点</th></tr></thead><tbody><tr><td>Webpack</td><td>功能强大、可高度定制、生态成熟，适合复杂工程</td></tr><tr><td>Parcel</td><td>零配置上手快，适合中小项目</td></tr><tr><td>Vite</td><td>基于 ES Module 和原生浏览器支持，开发体验好，冷启动快</td></tr></tbody></table><hr><h3 id="_2️⃣-loader-和-plugin-区别" tabindex="-1">2️⃣ Loader 和 Plugin 区别 <a class="header-anchor" href="#_2️⃣-loader-和-plugin-区别" aria-label="Permalink to “2️⃣ Loader 和 Plugin 区别”">​</a></h3><table tabindex="0"><thead><tr><th>Loader</th><th>Plugin</th></tr></thead><tbody><tr><td>本质是函数，处理模块内容</td><td>插件是类，在构建生命周期钩子上扩展功能</td></tr><tr><td>用于转换文件类型，如 css-loader, babel-loader</td><td>用于增强构建过程，如 HtmlWebpackPlugin, DefinePlugin</td></tr><tr><td>写在 <code>module.rules</code> 中</td><td>写在 <code>plugins</code> 配置中</td></tr></tbody></table><hr><h3 id="_3️⃣-常用的-loader-和-plugin" tabindex="-1">3️⃣ 常用的 Loader 和 Plugin <a class="header-anchor" href="#_3️⃣-常用的-loader-和-plugin" aria-label="Permalink to “3️⃣ 常用的 Loader 和 Plugin”">​</a></h3><h4 id="loader" tabindex="-1">Loader <a class="header-anchor" href="#loader" aria-label="Permalink to “Loader”">​</a></h4><ul><li><code>babel-loader</code>：转译 ES6+ 代码</li><li><code>css-loader</code>：处理 CSS 文件</li><li><code>style-loader</code>：将 CSS 插入 DOM</li><li><code>file-loader</code>：处理文件资源</li><li><code>url-loader</code>：小文件转 base64</li></ul><h4 id="plugin" tabindex="-1">Plugin <a class="header-anchor" href="#plugin" aria-label="Permalink to “Plugin”">​</a></h4><ul><li><code>HtmlWebpackPlugin</code>：生成 html 文件</li><li><code>DefinePlugin</code>：定义全局常量</li><li><code>CleanWebpackPlugin</code>：清理 dist 目录</li><li><code>MiniCssExtractPlugin</code>：提取 CSS 文件</li><li><code>HotModuleReplacementPlugin</code>：热更新</li></ul><hr><h3 id="_4️⃣-如何优化-webpack-构建速度" tabindex="-1">4️⃣ 如何优化 Webpack 构建速度？ <a class="header-anchor" href="#_4️⃣-如何优化-webpack-构建速度" aria-label="Permalink to “4️⃣ 如何优化 Webpack 构建速度？”">​</a></h3><ul><li>使用 <code>exclude</code> / <code>include</code> 限制 loader 处理范围</li><li>开启 <code>thread-loader</code> 或 <code>cache-loader</code></li><li>使用 <code>DLLPlugin</code> / <code>DLLReferencePlugin</code></li><li>开启 Webpack 5 持久化缓存</li><li>开启 HMR（热更新）</li><li>使用 <code>esbuild-loader</code> 或 <code>swc-loader</code> 替代 babel-loader</li></ul><hr><h3 id="_5️⃣-如何优化-webpack-打包体积" tabindex="-1">5️⃣ 如何优化 Webpack 打包体积？ <a class="header-anchor" href="#_5️⃣-如何优化-webpack-打包体积" aria-label="Permalink to “5️⃣ 如何优化 Webpack 打包体积？”">​</a></h3><ul><li>Tree-shaking（删除未使用代码）</li><li>SplitChunks（代码分割，提取公用包）</li><li>动态导入（按需加载）</li><li>使用生产模式 + 压缩插件（TerserPlugin、CssMinimizerPlugin）</li><li>替换大库（如用 <code>lodash-es</code> + <code>babel-plugin-lodash</code>）</li></ul><hr><h3 id="_6️⃣-如何实现代码分割" tabindex="-1">6️⃣ 如何实现代码分割？ <a class="header-anchor" href="#_6️⃣-如何实现代码分割" aria-label="Permalink to “6️⃣ 如何实现代码分割？”">​</a></h3><ul><li>配置 <code>splitChunks</code> 提取公共依赖</li><li>使用 <code>import()</code> 实现动态加载</li><li>多入口配置</li></ul><hr><h3 id="_7️⃣-webpack-热更新-hmr-原理" tabindex="-1">7️⃣ Webpack 热更新（HMR）原理 <a class="header-anchor" href="#_7️⃣-webpack-热更新-hmr-原理" aria-label="Permalink to “7️⃣ Webpack 热更新（HMR）原理”">​</a></h3><ul><li>Webpack 通过 WebSocket 和浏览器通信</li><li>检测到文件变化后生成更新的模块</li><li>浏览器接收到更新消息后，替换已更新的模块，而不刷新整个页面</li></ul><hr><h3 id="_8️⃣-tree-shaking-原理与生效条件" tabindex="-1">8️⃣ Tree-shaking 原理与生效条件 <a class="header-anchor" href="#_8️⃣-tree-shaking-原理与生效条件" aria-label="Permalink to “8️⃣ Tree-shaking 原理与生效条件”">​</a></h3><ul><li>Tree-shaking 利用 ES6 module 的静态分析特性，移除未使用的导出</li><li>生效条件： <ul><li>使用 ES6 模块语法（<code>import</code> / <code>export</code>）</li><li>开启生产模式（<code>mode: &#39;production&#39;</code>）</li><li>配置 <code>sideEffects: false</code>（或精准配置）</li></ul></li></ul><hr><h3 id="_9️⃣-webpack-构建流程" tabindex="-1">9️⃣ Webpack 构建流程 <a class="header-anchor" href="#_9️⃣-webpack-构建流程" aria-label="Permalink to “9️⃣ Webpack 构建流程”">​</a></h3>',36))])}const P=i(n,[["render",b]]);export{m as __pageData,P as default};
